pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";

/// @dev A question-pinned leaf with PriceFeed's span policy (300..1200 blocks) and the shipped
/// deployment bounds (maxAge 1 hour, maxDeviationBps 5000). The attester is a test key because the
/// shipped artifacts pin the oracle service's key; the check under test lives in SwarmFeed.
contract LagFeed is SwarmFeed {
    constructor(address attester_) SwarmFeed(attester_, address(0), 1, 3, 1 hours, 5000) {}

    function questionPolicy() internal pure override returns (bytes memory, uint64, uint64) {
        return ('{"answerType":"uint256","chainId":1,"question":"q","v":1,"window":{"fromBlock":', 300, 1200);
    }
}

/// @notice On a same-chain deployment (data chain == consumer chain == mainnet), an attestation that
/// answers the pinned question over a window that closed DAYS before the current block is accepted,
/// provided only that its toBlock is later than the last accepted one. A buyer therefore picks, from
/// every block since the last update, the window whose price suits them, has it freshly signed, and
/// the vault treats it as a fresh price. Expected: a window that lags the chain head by far more than
/// the feed's lifetime is refused. Actual: it is accepted and becomes the live price.
contract WindowLagTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    LagFeed private feed;

    function setUp() public {
        vm.chainId(1); // mainnet: the feed runs on the chain the question is asked about
        vm.warp(1_800_000_000);
        vm.roll(26_000_600);
        feed = new LagFeed(vm.addr(ATTESTER_KEY));
    }

    function test_aWindowThatClosedDaysAgoIsRefusedWhenFreshlySigned() public {
        // Honest update: window closed ten blocks ago, signed now.
        SwarmFeed.OracleAttestation memory first = _attestation(1 ether, 26_000_000, 26_000_590);
        feed.submitAttestation(first, _sign(first));
        (uint256 value,) = feed.latestValue();
        assertEq(value, 1 ether);

        // Three days pass with no update (the price feed is refreshed on demand, not on a clock).
        vm.warp(block.timestamp + 3 days);
        vm.roll(block.number + 21_600);
        assertTrue(feed.isStale(), "a quiet feed is stale between updates");

        // A window that closed three days ago, immediately after the last accepted one, answering the
        // pinned question exactly, freshly signed: the price the buyer wanted.
        SwarmFeed.OracleAttestation memory cherry = _attestation(2 ether, 26_000_591, 26_000_891);
        bytes memory sig = _sign(cherry);
        assertGt(block.number - cherry.toBlock, 20_000, "the window lags the head by days");
        vm.expectRevert();
        feed.submitAttestation(cherry, sig);

        (value,) = feed.latestValue();
        assertEq(value, 1 ether, "a days-old window must not become the live price");
    }

    function _attestation(uint256 figure, uint64 fromBlock, uint64 toBlock)
        private
        view
        returns (SwarmFeed.OracleAttestation memory a)
    {
        a.requestId = keccak256(abi.encode(figure, fromBlock, toBlock));
        a.chainId = 1;
        a.questionHash = feed.expectedQuestionHash(fromBlock, toBlock);
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = fromBlock;
        a.toBlock = toBlock;
        // What the plane signs: the real hash of the window's closing block. Inside the EVM's 256-block
        // horizon that is what blockhash returns; beyond it the chain can no longer vouch for it.
        a.blockHash = blockhash(toBlock) != bytes32(0) ? blockhash(toBlock) : keccak256(abi.encode(toBlock));
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 hours);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure
                ),
                abi.encode(
                    a.fromBlock, a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

