pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";
import {SwarmRelay} from "src/SwarmRelay.sol";
import {OracleAsker} from "src/OracleAsker.sol";
import {MockIMD} from "src/MockIMD.sol";
import {IIntake} from "src/interfaces/IIntake.sol";
import {APPROVED_OPERATOR, INTAKE, ORACLE_ACTION, ATTESTATION_RELAYER} from "src/DeploymentConfig.sol";

/// @dev A feed leaf that pins no question but takes the relay as its relayer, so the test can sign as
/// the attester. The asker's bookkeeping under test does not depend on the question policy.
contract ScratchFeed is SwarmFeed {
    constructor(address attester_, address relayer_) SwarmFeed(attester_, relayer_, 1, 3, 1 days, 2000) {}

    function seed(uint256 value) external {
        _accept(value, uint64(block.timestamp));
    }
}

/// @dev The Intake as PR #66 behaves: collects the price, records the callback, and on `complete`
/// calls the target once with a fixed stipend, recording rather than requiring the outcome.
contract ScratchIntake {
    mapping(bytes32 => mapping(address => uint256)) public priceOf;
    mapping(bytes32 => IIntake.Callback) public callbackOf;
    uint256 public nonce;

    function setPrice(bytes32 action, address asset, uint256 amount) external {
        priceOf[action][asset] = amount;
    }

    function request(bytes32 action, bytes calldata, IIntake.Callback calldata callback, address asset, uint256 amount)
        external
        payable
        returns (bytes32 requestId)
    {
        uint256 price = priceOf[action][asset];
        require(price != 0 && amount >= price, "not sold");
        IERC20(asset).transferFrom(msg.sender, address(this), amount);
        requestId = keccak256(abi.encode(block.chainid, address(this), ++nonce));
        callbackOf[requestId] = callback;
    }

    function complete(bytes32 requestId, bytes calldata args) external returns (bool delivered) {
        IIntake.Callback memory c = callbackOf[requestId];
        (delivered,) = c.target.call{gas: 200_000}(bytes.concat(c.selector, args));
    }
}

/// @notice Finding: a bought attestation that reaches the feed by any route other than the Intake's
/// callback (a keeper relaying it by hand, bundled with a bite) makes the callback revert on
/// ReplayedAttestation, so the asker never clears its in-flight slot: `ask` and `askPaid` are both
/// refused for that feed for ASK_TIMEOUT (two hours) although the feed is fresh and the request
/// was served. Fails on the current code; passes once `onOracleResult` treats an attestation the
/// feed has already consumed (`usedRequests`) as delivered and frees the slot.
contract AskerStuckInFlightTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    address private constant STRANGER = address(0x5757);
    address private constant BORROWER = address(0xB0B);
    uint256 private constant PRICE = 0.5 ether;
    bytes private constant BODY = '{"question":"network health"}';

    MockIMD private imd;
    ScratchIntake private intake;
    ScratchFeed private feed;
    OracleAsker private asker;

    function setUp() public {
        vm.chainId(11155111);
        vm.warp(10 days);
        vm.roll(1_000);
        vm.etch(ATTESTATION_RELAYER, address(new SwarmRelay()).code);
        vm.etch(INTAKE, address(new ScratchIntake()).code);
        intake = ScratchIntake(INTAKE);
        imd = new MockIMD();
        intake.setPrice(ORACLE_ACTION, address(imd), PRICE);
        feed = new ScratchFeed(vm.addr(ATTESTER_KEY), ATTESTATION_RELAYER);
        address[] memory feeds = new address[](1);
        feeds[0] = address(feed);
        bytes32[] memory hashes = new bytes32[](1);
        hashes[0] = keccak256(BODY);
        bool[] memory tracks = new bool[](1);
        bool[] memory keepAlive = new bool[](1);
        keepAlive[0] = true;
        asker = new OracleAsker(IERC20(address(imd)), feeds, hashes, tracks, keepAlive);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(address(asker), 100 ether);
        imd.mint(BORROWER, 10 ether);
        vm.stopPrank();
        feed.seed(0.9 ether);
    }

    function test_aHandRelayedAnswerMustNotLeaveTheAskerInFlightForTwoHours() public {
        // The Treasury-paid ask: the kept-alive feed is 75% of the way to stale.
        vm.warp(block.timestamp + 18 hours);
        bytes32 id = asker.ask(address(feed), BODY);

        // The answer is public the moment it is signed. A keeper (or anyone) relays it by hand,
        // bundled with whatever it enables, before the Intake's writer calls back.
        SwarmFeed.OracleAttestation memory a = _attestation(keccak256("served"), 0.88 ether);
        bytes memory sig = _sign(a);
        vm.prank(STRANGER);
        SwarmRelay(ATTESTATION_RELAYER).relay(feed, a, sig);
        (uint256 value,) = feed.latestValue();
        assertEq(value, 0.88 ether, "the feed holds the bought answer");
        assertFalse(feed.isStale());

        // The writer's callback: on the current code the relay reverts ReplayedAttestation and the
        // asker's state is rolled back, so the request it paid for and that was served stays in flight.
        intake.complete(id, abi.encode(id, a, sig));

        (,,,,, uint64 inFlightAt, bytes32 inFlight) = asker.feeds(address(feed));
        // EXPECTED: the asker recognises that the feed consumed the attestation and frees the slot.
        // ACTUAL: the slot stays occupied until ASK_TIMEOUT (two hours).
        assertEq(inFlight, bytes32(0), "a served request must not remain in flight");
        assertEq(inFlightAt, 0, "a served request must not remain in flight");

        // And so a borrower who wants a fresh answer for their own IMD an hour later can buy one.
        vm.warp(block.timestamp + 1 hours);
        vm.startPrank(BORROWER);
        imd.approve(address(asker), PRICE);
        asker.askPaid(address(feed), BODY, PRICE);
        vm.stopPrank();
    }

    function _attestation(bytes32 id, uint256 figure) private view returns (SwarmFeed.OracleAttestation memory a) {
        a.requestId = id;
        a.chainId = 1;
        a.questionHash = keccak256("q");
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = 100;
        a.toBlock = 200;
        a.blockHash = keccak256("b");
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 hours);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(), a.requestId, a.chainId, a.questionHash, a.answerType,
                    keccak256(a.answer), a.figure
                ),
                abi.encode(
                    a.fromBlock, a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed,
                    a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

