// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";

/// @dev A leaf that pins a question the way PriceFeed does (same mechanism: SwarmFeed._requireQuestion
/// splices the signed window onto a pinned prefix). The attester is a test key so the test can sign.
contract BoundLeaf is SwarmFeed {
    constructor(address attester_) SwarmFeed(attester_, address(0), 1, 3, 1 hours, 2000) {}

    function questionPolicy() internal pure override returns (bytes memory, uint64, uint64) {
        return ('{"answerType":"uint256","chainId":1,"question":"q","v":1,"window":{"fromBlock":', 300, 1200);
    }
}

/// @notice Finding: the window a pinned-question attestation answers over is bound only to the LAST
/// ACCEPTED window (toBlock must advance), never to the present block. Freshness is measured from
/// `issuedAt`, the signing time. So once a feed has been quiet for a while, an attestation signed now
/// over any window that closed just after the last accepted one — days before the present — is
/// accepted and reads as fresh for maxAge, and the vault prices collateral at a days-old market.
contract WindowLagTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    BoundLeaf private feed;

    function setUp() public {
        vm.chainId(1);
        vm.warp(10 days);
        vm.roll(26_000_700);
        feed = new BoundLeaf(vm.addr(ATTESTER_KEY));
    }

    function test_aWindowThatClosedTwoDaysAgoIsRefusedWhenSignedNow() public {
        // Day 0: an honest attestation over a window that just closed. Accepted.
        SwarmFeed.OracleAttestation memory a = _attestation(26_000_000, 26_000_600, 3_000_000_000_000_000);
        feed.submitAttestation(a, _sign(a));
        assertFalse(feed.isStale());

        // Two days pass with no update (prices are bought on demand, not on a clock).
        vm.warp(block.timestamp + 2 days);
        vm.roll(block.number + 14_400);
        assertTrue(feed.isStale(), "quiet feed is stale");

        // Day 2: an attestation SIGNED NOW over the window that opened right after the last accepted
        // one, i.e. one that closed ~2 days ago. The span is in bounds, toBlock advances, the question
        // hash matches, issuedAt is now. Expected: refused, because the window is ancient relative to
        // the present. Actual: accepted and the feed reads fresh at the two-day-old figure.
        SwarmFeed.OracleAttestation memory old_ = _attestation(26_000_601, 26_001_201, 3_000_000_000_000_000);
        bytes memory sig = _sign(old_);
        vm.expectRevert();
        feed.submitAttestation(old_, sig);
        assertTrue(feed.isStale(), "a two-day-old reading must not become the fresh price");
    }

    function test_positiveControl_aCurrentWindowIsStillAccepted() public {
        SwarmFeed.OracleAttestation memory a = _attestation(26_000_000, 26_000_600, 3_000_000_000_000_000);
        feed.submitAttestation(a, _sign(a));
        vm.warp(block.timestamp + 2 days);
        vm.roll(block.number + 14_400);
        // A window that closed a few blocks ago is what an honest, freshly bought attestation looks like.
        uint64 to = uint64(block.number - 10);
        SwarmFeed.OracleAttestation memory b = _attestation(to - 600, to, 2_900_000_000_000_000);
        feed.submitAttestation(b, _sign(b));
        assertFalse(feed.isStale());
    }

    function _attestation(uint64 fromBlock, uint64 toBlock, uint256 figure)
        private
        view
        returns (SwarmFeed.OracleAttestation memory a)
    {
        a.requestId = keccak256(abi.encode(fromBlock, toBlock, figure));
        a.chainId = 1;
        a.questionHash = feed.expectedQuestionHash(fromBlock, toBlock);
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = fromBlock;
        a.toBlock = toBlock;
        a.blockHash = blockhash(toBlock);
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 days);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure
                ),
                abi.encode(
                    a.fromBlock, a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

