        IERC20(asset).transferFrom(msg.sender, address(this), amount);
        requestId = keccak256(abi.encode(block.chainid, address(this), ++nonce));
        callbackOf[requestId] = callback;
    }

    function complete(bytes32 requestId, bytes calldata args) external returns (bool delivered) {
        IIntake.Callback memory c = callbackOf[requestId];
        (delivered,) = c.target.call{gas: 200_000}(bytes.concat(c.selector, args));
    }
}

/// @dev Unbound test leaf behind the pinned relay, as the asker's own suite uses.
contract Leaf is SwarmFeed {
    constructor(address attester_) SwarmFeed(attester_, ATTESTATION_RELAYER, 1, 3, 1 days, 2000) {}

    function seed(uint256 value) external {
        _accept(value, uint64(block.timestamp));
    }
}

/// @notice Finding: an attestation the Intake is about to deliver is public, and SwarmRelay is
/// permissionless. If anyone relays it by hand before the Intake's completion lands (a keeper
/// bundling `relayAndBite`, or a griefer), the Intake's callback reverts with ReplayedAttestation and
/// `onOracleResult` never clears the feed's in-flight slot. `ask` and `askPaid` for that feed are then
/// refused with InFlight for ASK_TIMEOUT (2 hours), even though the feed holds the delivered figure.
contract AskerReplayRaceTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    address private constant STRANGER = address(0x5757);
    uint256 private constant PRICE = 0.5 ether;

    MockIMD private imd;
    ScratchIntake private intake;
    Leaf private feed;
    OracleAsker private asker;
    bytes private constant BODY = '{"question":"network health"}';

    function setUp() public {
        vm.chainId(11155111);
        vm.warp(10 days);
        vm.roll(1_000);
        vm.etch(ATTESTATION_RELAYER, address(new SwarmRelay()).code);
        vm.etch(INTAKE, address(new ScratchIntake()).code);
        intake = ScratchIntake(INTAKE);
        imd = new MockIMD();
        intake.setPrice(ORACLE_ACTION, address(imd), PRICE);
        feed = new Leaf(vm.addr(ATTESTER_KEY));
        address[] memory feeds = new address[](1);
        feeds[0] = address(feed);
        bytes32[] memory hashes = new bytes32[](1);
        hashes[0] = keccak256(BODY);
        bool[] memory tracks = new bool[](1);
        bool[] memory keepAlive = new bool[](1);
        keepAlive[0] = true;
        asker = new OracleAsker(IERC20(address(imd)), feeds, hashes, tracks, keepAlive);
        vm.prank(APPROVED_OPERATOR);
        imd.mint(address(asker), 100 ether);
        vm.prank(APPROVED_OPERATOR);
        imd.mint(STRANGER, 10 ether);
        feed.seed(0.9 ether);
    }

    function test_aHandRelayBeforeTheCallbackMustNotHoldTheSlotForTwoHours() public {
        vm.warp(block.timestamp + 20 hours); // 83% of the way to stale: the Treasury pays
        bytes32 id = asker.ask(address(feed), BODY);

        // The attestation is signed and public before the Intake's completion transaction lands.
        SwarmFeed.OracleAttestation memory a = _attestation(keccak256("req"), 0.88 ether);
        bytes memory sig = _sign(a);

        // Anyone relays it by hand first (a keeper bundling a liquidation does exactly this).
        vm.prank(STRANGER);
        SwarmRelay(ATTESTATION_RELAYER).relay(feed, a, sig);
        (uint256 value,) = feed.latestValue();
        assertEq(value, 0.88 ether, "the feed holds the figure");

        // The Intake then completes: the callback relays the same request id, the feed says
        // ReplayedAttestation, and onOracleResult reverts without clearing the in-flight slot.
        bool delivered = intake.complete(id, abi.encode(id, a, sig));
        assertFalse(delivered, "callback reverted on the replay");

        // Expected: the request was fulfilled (the feed holds exactly this attestation), so the
        // asker's slot is free and a borrower can buy the next update at once.
        // Actual: InFlight(id) for ASK_TIMEOUT.
        vm.startPrank(STRANGER);
        imd.approve(address(asker), PRICE);
        asker.askPaid(address(feed), BODY, PRICE);
        vm.stopPrank();
    }

    function _attestation(bytes32 id, uint256 figure) private view returns (SwarmFeed.OracleAttestation memory a) {
        a.requestId = id;
        a.chainId = 1;
        a.questionHash = keccak256("q");
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = 100;
        a.toBlock = 200;
        a.blockHash = keccak256("b");
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 hours);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure
                ),
                abi.encode(
                    a.fromBlock, a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

