pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";

/// @dev A question-bound leaf with the production PriceFeed's span policy (300..1200 blocks) and a
/// test attester, deployed on the chain its question is ABOUT (chainId 1), which is the mainnet
/// launch configuration: consumer chain == data chain, so block.number is comparable to the window.
contract RecencyBoundFeed is SwarmFeed {
    constructor(address attester_) SwarmFeed(attester_, address(0), 1, 3, 1 hours, 5000) {}

    function questionPolicy() internal pure override returns (bytes memory, uint64, uint64) {
        return ('{"answerType":"uint256","chainId":1,"question":"q","v":1,"window":{"fromBlock":', 300, 1200);
    }
}

/// @notice FAILS on the current SwarmFeed: a freshly signed attestation over a window that closed
/// a million blocks before the current head is accepted, because the only window check is
/// `toBlock > lastToBlock`. Passes once the feed refuses a window that is not recent relative to
/// block.number when the attestation's data chain is the chain the feed runs on.
contract WindowRecencyProof is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    RecencyBoundFeed private feed;

    function setUp() public {
        vm.chainId(1);
        vm.warp(1_800_000_000);
        vm.roll(30_000_000);
        feed = new RecencyBoundFeed(vm.addr(ATTESTER_KEY));
    }

    function test_aFreshlySignedAnswerOverAWindowAMillionBlocksOldIsRefused() public {
        // An honest update whose window closed 100 blocks before the head.
        SwarmFeed.OracleAttestation memory first =
            _attestation(2_730_000_000_000_000, 29_999_300, 29_999_600, keccak256("first"));
        feed.submitAttestation(first, _sign(first));
        assertEq(feed.lastToBlock(), 29_999_600);

        // The protocol does not keep price feeds alive on a clock: the feed lapses. Five months pass.
        vm.roll(31_000_000);
        vm.warp(block.timestamp + 150 days);
        assertTrue(feed.isStale(), "the price feed has lapsed, so the deviation bound is lifted");

        // A buyer now purchases an answer to the pinned question over a window that closed one
        // million blocks before the current head, at half the price, and relays it signed today.
        SwarmFeed.OracleAttestation memory ancient =
            _attestation(1_365_000_000_000_000, 30_000_000, 30_000_600, keccak256("ancient-but-advancing"));
        bytes memory sig = _sign(ancient);

        // Expected: refused, the window is not a reading of the market the vault is about to act in.
        // Actual on the current code: accepted, and the feed is fresh at a five-month-old price.
        vm.expectRevert();
        feed.submitAttestation(ancient, sig);
    }

    function _attestation(uint256 figure, uint64 fromBlock, uint64 toBlock, bytes32 id)
        private
        view
        returns (SwarmFeed.OracleAttestation memory a)
    {
        a.requestId = id;
        a.chainId = 1;
        a.questionHash = feed.expectedQuestionHash(fromBlock, toBlock);
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = fromBlock;
        a.toBlock = toBlock;
        a.blockHash = keccak256("b");
        a.panelJobId = keccak256("panel");
        a.panelSize = 100;
        a.quorum = 70;
        a.agreed = 90;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 hours);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure
                ),
                abi.encode(
                    a.fromBlock, a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

