import {Test} from "forge-std/Test.sol";
import {PriceFeed} from "src/PriceFeed.sol";
import {UsdPriceFeed} from "src/UsdPriceFeed.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {ATTESTATION_RELAYER, CHAINLINK_ETH_USD, PRICE_MAX_AGE} from "src/DeploymentConfig.sol";

/// @notice FAILS on the current code: on a chain where the pinned relayer and the pinned Chainlink
/// aggregator have no code (which is what Ethereum mainnet is for the two Sepolia addresses in
/// DeploymentConfig at this commit), PriceFeed and UsdPriceFeed construct successfully. The feed is
/// then permanently inert (nobody can be `relayer`) and the USD leg permanently stale, and both are
/// immutable, which is the launch-519 failure the rest of the repository guards against with
/// `code.length` checks (OracleAsker on INTAKE, Treasury on ORACLE_ASKER, CDPVault on the factory).
/// Passes once SwarmFeed refuses a nonzero relayer with no code and UsdPriceFeed refuses an
/// aggregator with no code.
contract PinnedAddressGuardsProof is Test {
    function setUp() public {
        vm.chainId(1);
        vm.warp(1_800_000_000);
        vm.roll(30_000_000);
        assertEq(ATTESTATION_RELAYER.code.length, 0, "the pinned relayer has no code on this chain");
        assertEq(CHAINLINK_ETH_USD.code.length, 0, "the pinned aggregator has no code on this chain");
    }

    function test_aFeedWhosePinnedRelayerHasNoCodeIsNotConstructible() public {
        // Expected: construction reverts, because no address can ever satisfy `msg.sender == relayer`.
        // Actual: a PriceFeed is deployed that refuses every submitAttestation with UnauthorizedRelayer.
        vm.expectRevert();
        new PriceFeed(PRICE_MAX_AGE, 5000);
    }

    function test_aUsdFeedWhosePinnedAggregatorHasNoCodeIsNotConstructible() public {
        // A real IMD/ETH leg, so the only thing wrong is the USD leg's address.
        vm.etch(ATTESTATION_RELAYER, hex"6000");
        PriceFeed leg = new PriceFeed(PRICE_MAX_AGE, 5000);
        // Expected: construction reverts, because the USD leg can never answer.
        // Actual: a UsdPriceFeed is deployed whose isStale() is true forever.
        vm.expectRevert();
        new UsdPriceFeed(ISwarmFeed(address(leg)));
    }
}

